// Nœud Code « Lecture » (mode : Run Once for All Items)
// Lit la réponse JSON de Claude et l'associe à la demande d'origine.
// Si la réponse est illisible, on escalade par sécurité (jamais de réponse auto sur un doute).
const demandes = $('Demandes').all();
const sorties = [];

$input.all().forEach((item, i) => {
  // Claude peut renvoyer un bloc « thinking » avant le texte : on prend le bloc de type « text ».
  const bloc = (item.json.content ?? []).find((c) => c.type === 'text');
  const brut = bloc?.text ?? '';
  let r;
  try {
    const m = brut.match(/\{[\s\S]*\}/);
    r = JSON.parse(m ? m[0] : brut);
  } catch (e) {
    r = {
      procedure: 'ERREUR_JSON',
      decision: 'escalader',
      procedure_citee: '',
      raison: 'Réponse illisible, escalade par sécurité',
      brouillon: brut,
    };
  }
  sorties.push({
    json: {
      id: demandes[i].json.id,
      demande: demandes[i].json.demande,
      procedure: r.procedure,
      decision: r.decision,
      procedure_citee: r.procedure_citee,
      raison: r.raison,
      brouillon: r.brouillon,
      input_tokens: item.json.usage?.input_tokens ?? null,
      output_tokens: item.json.usage?.output_tokens ?? null,
    },
  });
});

return sorties;
